// scripts/lib/daily-assignment.mjs
// 修复：移除 ANS→DAILY 的 ID 重写，保持原 ID 供 task_board 索引；
// 在返回对象中增加 board_task_id 字段显式指向任务板原始 ID。
// 同时 run-daily-tasks.mjs 需要在 roleTask 前先通过 taskCommand claim。

export function dailyAssignment(agent, date, {control, pulse} = {}) {
  const age = index(date) - index(control?.date);
  const eligible = t => t.agent === agent && typeof t.instruction === 'string' && t.instruction.trim() && (!t.status || ['queued','queued_for_next_daily_economy','assigned'].includes(t.status));
  const dispatches = Array.isArray(control?.dispatches) ? control.dispatches : [];
  const scheduled = Number.isInteger(age) && age >= 0 && age <= 1
    ? dispatches.find(t => eligible(t) && ['queued','queued_for_next_daily_economy'].includes(t.status) && (t.execute_on ? t.execute_on === date : age === 1))
    : null;
  const explicit = scheduled || (control?.date === date ? dispatches.find(t => eligible(t) && (!t.execute_on || t.execute_on === date)) : null);
  if (explicit) {
    const issuedId = explicit.id || 'CONTROL-' + date + '-' + agent;
    const board = Array.isArray(pulse?.task_board) ? pulse.task_board : [];
    const boardTask = board.find(t => t.id === issuedId || t.id === explicit.board_task_id);
    const boardTaskId = boardTask?.id || issuedId;
    // 不再将 ANS-* 改写为 DAILY-*；身份由 task_board 已有条目承担。
    return {
      id: boardTaskId,
      instruction: explicit.instruction,
      source: control.dispatch_source || 'coordinator_record',
      source_date: control.date,
      execution_date: date,
      source_task_id: issuedId,
      board_task_id: boardTaskId
    };
  }
  const boardAll = Array.isArray(pulse?.task_board) ? pulse.task_board : [];
  const directed = boardAll.find(t => t.date === date && t.assigned_to === agent && t.status === 'assigned' && t.execution_chain === 'daily');
  if (directed) return {id: directed.id, instruction: directed.instruction, source: 'pulse_direct_assignment', execution_date: date, board_task_id: directed.id};
  const baseline = dailyBaselineDispatches(date).find(t => t.agent === agent);
  if (baseline) return {id: baseline.id, instruction: baseline.instruction, source: 'coordinator_rules_zero_model_baseline', execution_date: date, board_task_id: baseline.id};
  const open = boardAll.find(t => t.date === date && t.status === 'available' && !t.assigned_to);
  if (open) return {id: open.id, instruction: open.instruction, source: 'self_discovered_available_task_not_claim_proof', execution_date: date, board_task_id: open.id};
  return null;
}

